  for(let i=drops.length-1;i>=0;i--){let d=drops[i];d.bob+=dt*4;if(Math.hypot(player.x-d.x,player.y-d.y)<player.r+d.r+5){if(d.type==='heart'){if(player.hp<player.maxHp)player.hp=Math.min(player.maxHp,player.hp+2);else coins++;}else if(d.type==='coin')coins++;else keys++;particlesAt(d.x,d.y,d.type==='heart'?'#ff7189':'#ffd083',7);drops.splice(i,1);updateHud()}}
  for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.95;p.vy*=.95;p.life-=dt;if(p.life<=0)particles.splice(i,1)}
  if(!enemies.length&&!roomClear){roomClear=true;doors=[{x:W/2,y:walls.y-12},{x:W/2,y:walls.y+walls.h+12}];showToast(room%5===0?'The brute falls. A blessing awaits.':'Hatch unlocked — walk through!');if(room%5===0){setTimeout(()=>{if(state==='playing')chooseUpgrade()},650)}}
