function draw(){ctx.setTransform(scale,0,0,scale,ox,oy);ctx.clearRect(0,0,W,H);ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));
 // Background and stone chamber
 ctx.fillStyle='#171321';ctx.fillRect(0,0,W,H);ctx.fillStyle='#211a2a';ctx.fillRect(walls.x,walls.y,walls.w,walls.h);
 let grad=ctx.createRadialGradient(W/2,H/2,80,W/2,H/2,520);grad.addColorStop(0,'#2c2333');grad.addColorStop(1,'#1c1724');ctx.fillStyle=grad;ctx.fillRect(walls.x,walls.y,walls.w,walls.h);
 // subtle brick courses
 ctx.strokeStyle='#493849';ctx.lineWidth=1;for(let y=walls.y+13;y<walls.y+walls.h;y+=46){ctx.beginPath();ctx.moveTo(walls.x,y);ctx.lineTo(walls.x+walls.w,y);ctx.stroke();for(let x=walls.x+((Math.floor(y/46)%2)*44);x<walls.x+walls.w;x+=88){ctx.beginPath();ctx.moveTo(x,y-46);ctx.lineTo(x,y);ctx.stroke()}}
 decor.forEach(d=>{ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.r);ctx.strokeStyle=d.type==='crack'?'#514052':'#302838';ctx.lineWidth=1;if(d.type==='crack'){ctx.beginPath();ctx.moveTo(-d.s,0);ctx.lineTo(-2,-2);ctx.lineTo(1,3);ctx.lineTo(d.s,-2);ctx.stroke()}else{ctx.fillStyle='#382d3a';ctx.beginPath();ctx.ellipse(0,0,d.s,d.s*.45,0,0,Math.PI*2);ctx.fill()}ctx.restore()});
 // Wall edges and corner details
 ctx.fillStyle='#302436';ctx.fillRect(walls.x-8,walls.y-12,walls.w+16,16);ctx.fillRect(walls.x-8,walls.y+walls.h-4,walls.w+16,16);ctx.fillRect(walls.x-8,walls.y,16,walls.h);ctx.fillRect(walls.x+walls.w-8,walls.y,16,walls.h);ctx.strokeStyle='#705064';ctx.lineWidth=2;ctx.strokeRect(walls.x-2,walls.y-5,walls.w+4,walls.h+10);
 for(let x=walls.x+12;x<walls.x+walls.w;x+=48){ctx.fillStyle='#453448';ctx.fillRect(x,walls.y-9,3,7);ctx.fillRect(x,walls.y+walls.h+3,3,7)}
 // Hatch
 if(roomClear&&room%5!==0){let hx=W/2,hy=walls.y-6;ctx.fillStyle='#100d18';ctx.fillRect(hx-34,hy-8,68,17);ctx.fillStyle='#8c6750';ctx.fillRect(hx-25,hy-4,50,10);ctx.fillStyle='#dfb36c';ctx.fillRect(hx-17,hy-2,34,5);ctx.fillStyle='#fff0b0';ctx.fillRect(hx-3,hy-2,6,5)}
 // Particles beneath actors
 particles.forEach(p=>{ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill()});ctx.globalAlpha=1;
 drops.forEach(d=>{let bob=Math.sin(d.bob)*3;ctx.save();ctx.translate(d.x,d.y+bob);ctx.shadowBlur=14;ctx.shadowColor=d.type==='heart'?'#ff536f':'#ffd06d';ctx.fillStyle=d.type==='heart'?'#ff7388':d.type==='coin'?'#ffd27c':'#bde6d7';ctx.beginPath();if(d.type==='heart'){ctx.moveTo(0,7);ctx.bezierCurveTo(-13,-1,-8,-10,-2,-7);ctx.bezierCurveTo(2,-11,11,-7,7,0);ctx.lineTo(0,7)}else{ctx.arc(0,0,d.r,0,Math.PI*2)}ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff2d6';ctx.fillRect(-2,-3,3,3);ctx.restore()});
 foes.forEach(b=>{ctx.fillStyle='#ff947c';ctx.shadowColor='#ff6a8b';ctx.shadowBlur=9;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0});
 tears.forEach(b=>{ctx.fillStyle='#d5fbff';ctx.shadowColor='#9ceeff';ctx.shadowBlur=12;ctx.beginPath();ctx.ellipse(b.x,b.y,b.r,b.r*1.25,Math.atan2(b.vy,b.vx),0,Math.PI*2);ctx.fill();ctx.shadowBlur=0});
 enemies.forEach(e=>{ctx.save();ctx.translate(e.x,e.y);let bob=Math.sin(e.phase*4)*1.5;ctx.translate(0,bob);ctx.shadowColor='#09070e';ctx.shadowBlur=8;ctx.shadowOffsetY=5;let body=e.type==='brute'?'#a7545c':e.type==='spitter'?'#737f8d':'#95677b';ctx.fillStyle=e.flash>0?'#ffe9d0':body;ctx.beginPath();ctx.ellipse(0,0,e.r*1.08,e.r*.88,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.shadowOffsetY=0;
 if(e.type==='brute'){ctx.fillStyle='#5e353f';ctx.beginPath();ctx.moveTo(-13,-13);ctx.lineTo(-21,-27);ctx.lineTo(-4,-19);ctx.moveTo(13,-13);ctx.lineTo(21,-27);ctx.lineTo(4,-19);ctx.fill();ctx.fillStyle='#ffcc7a';ctx.fillRect(-9,-4,5,4);ctx.fillRect(5,-4,5,4);ctx.fillStyle='#431f35';ctx.fillRect(-5,7,10,3)}else if(e.type==='spitter'){ctx.fillStyle='#f0c77e';ctx.beginPath();ctx.arc(-5,-2,2.4,0,7);ctx.arc(5,-2,2.4,0,7);ctx.fill();ctx.fillStyle='#463749';ctx.beginPath();ctx.arc(0,6,5,0,Math.PI*2);ctx.fill()}else{ctx.fillStyle='#ffe2aa';ctx.beginPath();ctx.ellipse(-5,-3,2,3,0,0,7);ctx.ellipse(5,-3,2,3,0,0,7);ctx.fill();ctx.fillStyle='#4b293a';ctx.fillRect(-4,6,8,2)}
 if(e.hp<e.maxHp){ctx.fillStyle='#100d18';ctx.fillRect(-e.r,-e.r-10,e.r*2,3);ctx.fillStyle='#ff8790';ctx.fillRect(-e.r,-e.r-10,e.r*2*e.hp/e.maxHp,3)}ctx.restore()});
 // Player shadow and little frightened hero
 if(player){ctx.save();ctx.translate(player.x,player.y);let blink=player.inv>0&&Math.floor(t*18)%2===0;ctx.globalAlpha=blink?.45:1;ctx.shadowColor='#000';ctx.shadowBlur=9;ctx.shadowOffsetY=5;ctx.fillStyle='#e2b9a6';ctx.beginPath();ctx.ellipse(0,0,12,14,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.fillStyle='#f2d5bd';ctx.beginPath();ctx.arc(0,-3,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#674653';ctx.beginPath();ctx.ellipse(0,-8,10,6,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#30202e';ctx.beginPath();ctx.ellipse(-3,-3,1.5,2.4,0,0,7);ctx.ellipse(3,-3,1.5,2.4,0,0,7);ctx.fill();ctx.strokeStyle='#986776';ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,2,2.5,.1,Math.PI-.1);ctx.stroke();ctx.restore()}
 ctx.restore();if(flash>0){ctx.fillStyle=`rgba(255,60,90,${flash*1.7})`;ctx.fillRect(0,0,W,H)}
}
function frame(now){let dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame)}
function keydown(e){let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keysDown[k]=true;if(k===' '&&!e.repeat)dash();if(k==='escape'){if(state==='playing'){state='paused';document.querySelectorAll('.screen').forEach(x=>x.classList.add('hidden'));document.getElementById('pause').classList.remove('hidden');overlay.classList.remove('hidden')}else if(state==='paused'){state='playing';overlay.classList.add('hidden')}}if(state==='upgrade'&&['1','2','3'].includes(k)){document.querySelectorAll('.choice')[Number(k)-1]?.click()}}
function keyup(e){keysDown[e.key.toLowerCase()]=false}
function refreshInput(){let x=(keysDown.d||keysDown.arrowright?1:0)-(keysDown.a||keysDown.arrowleft?1:0),y=(keysDown.s||keysDown.arrowdown?1:0)-(keysDown.w||keysDown.arrowup?1:0);if(stickPointer!==null&&stickOrigin){x+=input.stickX||0;y+=input.stickY||0}input.x=x;input.y=y}
window.addEventListener('keydown',keydown);window.addEventListener('keyup',keyup);window.addEventListener('blur',()=>{keysDown={};input.x=input.y=0});
const stick=document.getElementById('stick'),nub=document.getElementById('nub');
stick.addEventListener('pointerdown',e=>{if(state!=='playing')return;stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);let r=stick.getBoundingClientRect();stickOrigin={x:r.left+r.width/2,y:r.top+r.height/2};moveStick(e)});
function moveStick(e){if(stickPointer!==e.pointerId||!stickOrigin)return;let dx=e.clientX-stickOrigin.x,dy=e.clientY-stickOrigin.y,d=Math.hypot(dx,dy),max=39;if(d>max){dx*=max/d;dy*=max/d}input.stickX=dx/max;input.stickY=dy/max;nub.style.transform=`translate(${dx}px,${dy}px)`;refreshInput()}
stick.addEventListener('pointermove',moveStick);function endStick(e){if(stickPointer!==e.pointerId)return;stickPointer=null;stickOrigin=null;input.stickX=input.stickY=0;nub.style.transform='';refreshInput()}stick.addEventListener('pointerup',endStick);stick.addEventListener('pointercancel',endStick);
document.getElementById('dashbtn').addEventListener('pointerdown',e=>{e.preventDefault();dash()});
document.getElementById('startbtn').onclick=start;document.getElementById('restartbtn').onclick=start;document.getElementById('resumebtn').onclick=()=>{state='playing';overlay.classList.add('hidden')};
// Keep input responsive while key states change.
window.addEventListener('keydown',refreshInput);window.addEventListener('keyup',refreshInput);
requestAnimationFrame(now=>{last=now;frame(now)});
})();
</script></body></html>

